) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;






CREATE TABLE `hesk_temp_attachments` (
  `att_id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT,
