INSERT INTO hesk_tickets VALUES("2","D7M-9A2-4PUR","Justin Petrozzi","jpetrozzi@countrysidedodge.com","6","1","Request from Justin Petrozzi","Parts Advisor replacement","Parts Advisor replacement","2023-06-13 08:36:24","2023-06-13 09:07:40","2023-06-13 08:41:04","2023-06-13 09:07:40","","24.51.227.58","","3","183","236","236","4","4","236","","00:01:45","1","236","0","0","6#Logen-Deshane-2022.pdf,","","<li class=\"smaller\">2023-06-13 11:36:23 | request created by Justin Petrozzi (jpetrozzi)</li><li class=\"smaller\">2023-06-13 11:39:56 | assigned to Sherri Holmes (sholmes) by Deanna Muir (dmuir)</li><li class=\"smaller\">2023-06-13 11:40:58 | assigned to Zeyad Rafih (zr) by Sherri Holmes (sholmes)</li><li class=\"smaller\">2023-06-13 11:41:04 | status changed to Approved by Sherri Holmes (sholmes)</li><li class=\"smaller\">2023-06-13 12:06:07 | status changed to Waiting reply by Sherri Holmes (sholmes)</li><li class=\"smaller\">2023-06-13 12:07:11 | assigned to Justin Petrozzi (jpetrozzi) by Sherri Holmes (sholmes)</li><li class=\"smaller\">2023-06-13 12:07:35 | assigned to <i>Unassigned</i> by Sherri Holmes (sholmes)</li><li class=\"smaller\">2023-06-13 12:07:40 | assigned to Sherri Holmes (sholmes) by Sherri Holmes (sholmes)</li><li class=\"smaller\">2023-06-13 12:07:40 | status changed to Resolved by Sherri Holmes (sholmes)</li>","Countryside Chrysler","Parts","","","","","","","","","","","","","","","Parts Advisor","Full Time","Justin Petrozzi","1687132800","Replacement","$17.00 per hour","Hourly","Fixed ops","","No","","","","","","","","","","","","","","","","","","","","","","","","","","0","0","","");
INSERT INTO hesk_tickets VALUES("3","WB4-N5Q-VP9Y","Dan Spasojevic","dspasojevic@rafihautogroup.com","6","3","Request from Dan Spasojevic","This is an approved replacement to replace people that have left us. <br />\n<br />\nGeorge Sukru is very experienced and use to work at Go Auto at Mississuaga Chrysler and Go Auto old WhiteOak Ford.<br />\nHe is a very good Subprime Finance Manager and left us when we changed ownership for better pay plan. HE HAS BEEN AT HUNT CHRYSLER FOR LAST 3 AND A HALF YEARS after he left Go Auto where we worked together.<br />\n<br />\nPROPOSED PAY PLAN IS SAME EXCEPT THAT HE WILL NOT RUN A TEAM SO THERE WILL BE NO TEAM BONUS 5%!<br />\n<br />\nSame as Existing Pay plan - 25% of front and Back - No team bonus 5% - Instead of team bonus PLEASE INSERT - $1000 for 8 Deliveries, $1500 for 10 Deliveries and $2000 for 12 Deliveries!","This is an approved replacement to replace people that have left us. <br />\n<br />\nGeorge Sukru is very experienced and use to work at Go Auto at Mississuaga Chrysler and Go Auto old WhiteOak Ford.<br />\nHe is a very good Subprime Finance Manager and left us when we changed ownership for better pay plan. HE HAS BEEN AT HUNT CHRYSLER FOR LAST 3 AND A HALF YEARS after he left Go Auto where we worked together.<br />\n<br />\nPROPOSED PAY PLAN IS SAME EXCEPT THAT HE WILL NOT RUN A TEAM SO THERE WILL BE NO TEAM BONUS 5%!<br />\n<br />\nSame as Existing Pay plan - 25% of front and Back - No team bonus 5% - Instead of team bonus PLEASE INSERT - $1000 for 8 Deliveries, $1500 for 10 Deliveries and $2000 for 12 Deliveries!","2023-06-13 10:10:04","2023-06-15 08:03:12","2023-06-14 04:52:04","2023-06-15 08:03:12","","69.58.110.92","","3","215","236","236","3","3","36","236","00:02:26","1","236","0","0","","","<li class=\"smaller\">2023-06-13 13:10:04 | request created by Dan Spasojevic (dspasojevic)</li><li class=\"smaller\">2023-06-13 15:05:39 | assigned to Sherri Holmes (sholmes) by Deanna Muir (dmuir)</li><li class=\"smaller\">2023-06-14 07:51:49 | assigned to Scott (sstory) by Sherri Holmes (sholmes)</li><li class=\"smaller\">2023-06-14 07:52:04 | status changed to Waiting reply by Sherri Holmes (sholmes)</li><li class=\"smaller\">2023-06-14 10:03:07 | status changed to Approved by Scott (sstory)</li><li class=\"smaller\">2023-06-15 11:03:11 | status changed to Resolved by Sherri Holmes (sholmes)</li>","My Mississauga Chrysler","Management","","","","","","","","","","","","","","","Senior Subprime Finance Manager","Full Time","Serge Stanojevic","1686700800","Replacement","Same as Existing Pay plan - 25% of front and Back - No team bonus 5% - Instead of team bonus $1000 for 8 Deliveries, $1500 for 10 Deliveries and $2000 for 12 Deliveries,","BiWeekly","Fixed ops","","Yes","","","","","","","","","","","","","","","","","","","","","","","","","2023-06-13 21:00:00","0","0","","");
