INSERT INTO hesk_tickets VALUES("7","EQQ-WVN-NR4H","Dan","dlamberti@whiteoakfordlincoln.com","6","1","Request from Dan","Team,<br />\n<br />\nFrank comes with a wealth of Ford experience and his reference check out good. He is seeking an Assistant Service Manager role; I believe he would be an excellent addition to our team. Anees and I were discussing this role and have agreed that we would offer him the role of Senior Service Advisor / Service Advisor Team Leader with a promotion to Assistant Service Manager if he meets the 90 day probational period. <br />\n<br />\nBase: $55,000.00 plus pay plan attached<br />\n<br />\nThank you,<br />\n<br />\nDan Lamberti.","Team,<br />\n<br />\nFrank comes with a wealth of Ford experience and his reference check out good. He is seeking an Assistant Service Manager role; I believe he would be an excellent addition to our team. Anees and I were discussing this role and have agreed that we would offer him the role of Senior Service Advisor / Service Advisor Team Leader with a promotion to Assistant Service Manager if he meets the 90 day probational period. <br />\n<br />\nBase: $55,000.00 plus pay plan attached<br />\n<br />\nThank you,<br />\n<br />\nDan Lamberti.","2023-06-14 10:13:27","2023-07-07 07:35:12","2023-06-16 06:28:54","2023-07-07 07:35:12","","199.243.186.226","","3","179","214","236","2","2","214","","00:00:35","1","236","0","0","10#Frank_Bevacqua.pdf,11#Pay-Plan.jpg,","","<li class=\"smaller\">2023-06-14 13:13:26 | request created by Dan (dlamberti)</li><li class=\"smaller\">2023-06-16 09:28:33 | priority changed to High by Anees Haq (WHITEOAK FORD &amp; LINCLON) (ahaq)</li><li class=\"smaller\">2023-06-16 09:28:54 | assigned to Anees Haq (WHITEOAK FORD &amp; LINCLON) (ahaq) by Anees Haq (WHITEOAK FORD &amp; LINCLON) (ahaq)</li><li class=\"smaller\">2023-06-16 09:28:54 | status changed to Approved by Anees Haq (WHITEOAK FORD &amp; LINCLON) (ahaq)</li><li class=\"smaller\">2023-07-07 10:35:12 | statu