CREATE TABLE `hesk_tickets_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `description` varchar(255) NOT NULL,
  `quantity` int(11) NOT NULL,
  `budget` int(11) NOT NULL,
  `remarks` varchar(255) NOT NULL,
  `unit` varchar(255) NOT NULL,
  `card_name` varchar(255) NOT NULL,
  `title` varchar(255) NOT NULL,
  `business_phone` varchar(255) NOT NULL,
  `extension` varchar(255) NOT NULL,
  `card_email` varchar(255) NOT NULL,
  `cell` varchar(255) NOT NULL,
  `computer_type` varchar(255) NOT NULL,
  `computer_operating_system` varchar(255) NOT NULL,
  `computer_processor` varchar(255) NOT NULL,
  `computer_ram` varchar(255) NOT NULL,
  `computer_storage` varchar(255) NOT NULL,
  `computer_graphics` varchar(255) NOT NULL,
  `computer_screen` varchar(255) NOT NULL,
  `computer_keyboard` varchar(255) NOT NULL,
  `computer_mouse` varchar(255) NOT NULL,
  `computer_monitor` varchar(255) NOT NULL,
  `computer_budget` varchar(255) NOT NULL,
  `computer_comments` varchar(255) NOT NULL,
  `printer_make` varchar(255) NOT NULL,
  `printer_model` varchar(255) NOT NULL,
  `printer_used_by` varchar(255) NOT NULL,
  `printer_catridge_make` varchar(255) NOT NULL,
  `printer_catridge_model` varchar(255) NOT NULL,
  `printer_quantity` varchar(255) NOT NULL,
  `printer_budget` varchar(255) NOT NULL,
  `printer_comments` varchar(255) NOT NULL,
  `stationary_item` varchar(255) NOT NULL,
  `stationary_quantity` varchar(255) NOT NULL,
  `stationary_budget` varchar(255) NOT NULL,
  `stationary_remarks` varchar(255) NOT NULL,
  `ticket_id` varchar(255) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8;

